    def load_data_from_file(self, filename):
            self.data = {}  # Khởi tạo dict để lưu trữ dữ liệu

            # Đọc dữ liệu từ file
            with open(filename, 'r') as file:
                for line in file:
                    line = line.strip()
                    if line:
                        try:
                            country, area = line.split(": ")
                            country = country.strip("'")
                            area = area.strip("'")

                            # Tách phần trước và sau dấu '/'
                            area_prefix = area.split('/')[0]
                            country_suffix = area.split('/')[-1]

                            # Thêm vào dict
                            if area_prefix not in self.data:
                                self.data[area_prefix] = []
                            self.data[area_prefix].append(country_suffix)

                        except ValueError:
                            print(f"Lỗi phân tích cú pháp dòng: '{line}'")
                            continue

            # Cập nhật areaTxt
            for area in self.data.keys():
                self.areaTxt.addItem(area)

    def update_country_txt(self):
        selected_area = self.areaTxt.currentText()
        self.countryTxt.clear()  # Xóa các item hiện tại

        if selected_area in self.data:
            # Lọc và thêm các quốc gia tương ứng vào countryTxt
            for country in self.data[selected_area]:
                self.countryTxt.addItem(country)

        # Nếu không có phần sau dấu '/', thêm phần đó vào countryTxt
        elif selected_area:
            self.countryTxt.addItem(selected_area)

